{"intent":"Sweep boundary values and check output consistency invariant","command":"PYTHONPATH=work/repo/src python3 -c "
from humanize.filesize import naturalsize, suffixes
import re, random

def check(v, binary, gnu, fmt):
    out = naturalsize(v, binary=binary, gnu=gnu, format=fmt)
    suffix = suffixes['gnu' if gnu else ('binary' if binary else 'decimal')]
    base = 1024 if (gnu or binary) else 1000
    # split number and suffix
    m = re.match(r'^(-?[\d.e+]+)\s?(.*)$', out)
    num_s, sfx = m.group(1), m.group(2)
    if sfx not in suffix:
        return ('bad-suffix', out)
    idx = suffix.index(sfx)
    num = float(num_s)
    if abs(num) >= base and idx != len(suffix)-1:
        return ('num>=base', out)
    expected = v / base**(idx+1)
    if float(fmt % expected) != abs(num) and float(fmt % -expected) != num:
        return ('mismatch', out, fmt % expected)
    return None

bad = []
# boundary sweep for every unit, all modes, several formats
for fmt in ['%.1f', '%.2f', '%.0f', '%.3f', '%e']:
    for binary, gnu in [(False,False),(True,False),(False,True)]:
        suffix = suffixes['gnu' if gnu else ('binary' if binary else 'decimal')]
        base = 1024 if (gnu or binary) else 1000
        for i in range(len(suffix)):
            boundary = base**(i+1)
            for delta in [-3,-1,0,1,3, -base//2, -10, 10, base//2, 100, 1000, base-1]:
                v = boundary + delta
                if v < base: continue
                r = check(v, binary, gnu, fmt)
                if r: bad.append((v,binary,gnu,fmt,r))
random.seed(0)
for _ in range(3000):
    v = random.randint(1000, 10**31)
    fmt = random.choice(['%.1f','%.2f','%.0f'])
    binary, gnu = random.choice([(False,False),(True,False),(False,True)])
    r = check(v, binary, gnu, fmt)
    if r: bad.append((v,binary,gnu,fmt,r))
print('bad count:', len(bad))
for b in bad[:25]: print(b)
""}

