from humanize.filesize import naturalsize as n, suffixes
import re

def fails(v, binary, gnu, fmt):
    out = n(v, binary=binary, gnu=gnu, format=fmt)
    sfx = suffixes['gnu' if gnu else ('binary' if binary else 'decimal')]
    base = 1024 if (gnu or binary) else 1000
    m = re.match(r'^([-+0-9.e+]+)\s?(.*)$', out)
    num, s = float(m.group(1)), m.group(2)
    if s not in sfx: return ('sfx?', out)
    i = sfx.index(s)
    if abs(num) >= base and i != len(sfx)-1: return ('>=base', out)
    exp = v / base**(i+1)
    if float(fmt % exp) != abs(num): return ('mismatch', out, fmt % exp)
    return None

bad = []
for fmt in ['%g', '%+.1f', '%08.2f', '%.1e', '%.4g', '%.0e']:
    for binary, gnu in [(False,False),(True,False),(False,True)]:
        sfx = suffixes['gnu' if gnu else ('binary' if binary else 'decimal')]
        base = 1024 if (gnu or binary) else 1000
        for i in range(len(sfx)):
            b = base**(i+1)
            for d in [-1, -base//2, 0, 1, 10, base//2, base-1]:
                v = b + d
                if v < base: continue
                r = fails(v, binary, gnu, fmt)
                if r: bad.append((v, binary, gnu, fmt, r))
print('numeric-format failures:', len(bad), bad[:5])
# string inputs at boundary
print(repr(n('999960')), repr(n('-999960')), repr(n('1073741823', binary=True)))
# fallback path: formats that are legal for % but not parseable by float()
for fmt in ['%.1f%%', '%.1f bytes', '%.1f kB']:
    try:
        print(repr(fmt), repr(n(999_960, format=fmt)))
    except Exception as e:
        print(repr(fmt), 'raised', type(e).__name__, e)
