 'binary': dict(base=1024, suffix=suffixes['binary'], kwargs=dict(binary=True)),
 'gnu': dict(base=1024, suffix=suffixes['gnu'], kwargs=dict(gnu=True)),
}
formats = ["%.1f", "%.2f", "%.0f", "%.3f", "%.4f", "%.1e", "%.3g", "%d", "%6.1f", "%.15g"]

problems = []
for mode, m in modes.items():
    base, suf = m['base'], m['suffix']
    # candidate values: near every boundary
    vals = []
    for k in range(1, 12):
        b = base**k
        for d in [0, 1, 10, 40, 400, 40000, 400000, b//1000 - 1 if k>1 else 0]:
            if b + d >= base:
                vals.append(b + d)
            if b - d >= base:
                vals.append(b - d)
        # values that scale to ~999.96 at exp = k-1... (i.e. 999.96 * base**(k-1))
        if k >= 1:
            for frac in [999.94, 999.96, 999.99, 999.5, 999.9999, 1000.0]:
