// highest-level release crossed between the low core and the high core inclusive;
// when cores are identical, the level of that release itself.
// level(core) = patch if patch!=0, minor if minor!=0, else major
const lvl = (mi, p) => p ? 'patch' : (mi ? 'minor' : 'major');
const order = { patch: 1, minor: 2, major: 3 };

function boundaryDiff(a, b) {
  const v1 = parse(a, null, true), v2 = parse(b, null, true);
  const c = v1.compare(v2);
  if (c === 0) return null;
  const h = c > 0 ? v1 : v2, l = c > 0 ? v2 : v1;
  const hp = !!h.prerelease.length, lp = !!l.prerelease.length;
  if (lp && !hp) {
    let best = lvl(l.minor, l.patch);          // low's own target release (crossed when cores differ)
    const bh = lvl(h.minor, h.patch);
    if (order[bh] > order[best]) best = bh;
    if (h.major > l.major) best = 'major';
    if (h.major === l.major && h.minor > l.minor && order.minor > order[best]) best = 'minor';
    // if cores identical, only high's release counts (low target == high core)
    if (h.major === l.major && h.minor === l.minor && h.patch === l.patch) best = bh;
    return best;
