from boltons.setutils import IndexedSet, _MISSING
import random

def snap(iset):
    return (list(iset.item_list), dict(iset.item_index_map), [list(x) for x in iset.dead_indices])

def restore(iset, s):
    iset.item_list[:] = s[0]
    iset.item_index_map.clear(); iset.item_index_map.update(s[1])
    iset.dead_indices[:] = [list(x) for x in s[2]]

random.seed(7)
fails = []
for trial in range(300):
    n = random.randint(0, 15)
    iset = IndexedSet(range(n))
    ref = list(range(n))
    for _ in range(random.randint(0, n)):
        if not ref: break
        i = random.randrange(len(ref))
        v = ref.pop(i)
        if random.random() < 0.5:
            iset.remove(v)
        else:
            got = iset.pop(i)
            if got != v: fails.append(('popval', trial, got, v))
    if list(iset) != ref: fails.append(('contents', trial, list(iset), ref)); continue

    # pop bounds: probe every index in wide range, restore state each time
    for i in list(range(-3*n-3, 3*n+4)):
        s0 = snap(iset)
        try:
            got = repr(iset.pop(i))
        except IndexError:
            got = 'IndexError'
        except Exception as e:
            got = type(e).__name__ + ':' + str(e)
        s1 = snap(iset)
        restore(iset, s0)  # always restore
        try:
            model = repr(ref[i])
        except IndexError:
            model = 'IndexError'
        if got != model:
            fails.append(('popbounds', trial, n, i, got, model))
        # in-range successful pops must have mutated; out-of-range must not
        if model != 'IndexError' and s0 == s1:
            fails.append(('no_mutation_on_success', trial, i))
        if model == 'IndexError' and s0 != s1:
            fails.append(('mutation_on_error', trial, i, got))

    # getitem parity incl out-of-range
    for i in range(-3*n-3, 3*n+4):
        try: g = repr(iset[i])
        except IndexError: g = 'IndexError'
        except Exception as e: g = type(e).__name__
        try: e = repr(ref[i])
        except IndexError: e = 'IndexError'
        if g != e: fails.append(('getitem', trial, n, i, g, e))

    # slices parity with list (positive steps) and fresh set (all steps)
    fresh = IndexedSet(ref)
    for start in (None, -20, -10, -5, -1, 0, 2, 7, 15, 20):
        for stop in (None, -20, -10, -5, -1, 0, 2, 7, 15, 20):
            for step in (None, 1, 2, 3, 5, -1, -2, -3):
                sl = slice(start, stop, step)
                try: a = list(iset[sl])
                except Exception as e: a = ('EXC', type(e).__name__, str(e))
                try: b = list(fresh[sl])
                except Exception as e: b = ('EXC', type(e).__name__, str(e))
                if a != b: fails.append(('slice_vs_fresh', trial, n, sl, a, b))
                if step is None or step > 0:
                    try: c = ref[sl]
                    except Exception as e: c = ('EXC', type(e).__name__)
                    if a != c: fails.append(('slice_vs_list', trial, n, sl, a, c))

    # drain both fully
    while ref:
        iset.pop(); ref.pop()
    if list(iset) != [] or list(iset.item_list) != []:
        fails.append(('drain', trial, list(iset), list(iset.item_list)))
    try:
        iset.pop(); r='NOMISS'
