def run_module(path, modname):
    spec = importlib.util.spec_from_file_location(modname, path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    fixtures = {n: f for n, f in vars(mod).items()
                if callable(f) and getattr(f, '_is_fixture', False)}
    module_cache = {}
    passed = failed = 0
    failures = []
    for name in sorted(vars(mod)):
        fn = getattr(mod, name)
        if not (name.startswith('test') and callable(fn)): continue
        if getattr(fn, '_is_fixture', False): continue
        sig = inspect.signature(fn)
        argnames = list(sig.parameters)
        # build option lists per arg
        opt_lists = []
        for a in argnames:
            if getattr(fn, '_parametrize', None) and a in fn._parametrize[0]:
                names, values = fn._parametrize
                idx = names.index(a)
                vals = []
                for v in values:
                    vals.append(v[idx] if isinstance(v, (tuple, list)) else v)
                opt_lists.append(vals)
            elif a in fixtures:
                fx = fixtures[a]
                fparams = getattr(fx, '_params', None)
                if fparams is not None:
                    def make(fx=fx):
                        out = []
                        for p in fparams:
                            req = types.SimpleNamespace(param=p)
                            key = (fx, p)
                            if getattr(fx, '_scope', 'function') == 'module' and key in module_cache:
                                out.append(module_cache[key])
                            else:
                                val = fx(req)
                                if getattr(fx, '_scope', 'function') == 'module':
                                    module_cache[key] = val
                                out.append(val)
                        return out
                    opt_lists.append(make())
                else:
                    val = fx(types.SimpleNamespace(param=None))
                    opt_lists.append([val])
            else:
                raise RuntimeError(f'unresolvable fixture {a} for {name}')
        combos = itertools.product(*opt_lists) if opt_lists else [()]
        for combo in combos:
