          "m":-3,"μ":-6,"n":-9,"p":-12,"f":-15,"a":-18,"z":-21,"y":-24,"r":-27,"q":-30}

def parse(out, unit):
    body = out
    if unit:
        assert body.endswith(unit), out
        body = body[: -len(unit)]
    body = body.strip()
    m = re.fullmatch(r"(-?\d+(?:\.\d+)?)\s*([kMGTPEZYRQmμnpfazyrq]?)", body)
    if not m:
        return None, None
    return float(m.group(1)), PREFIX[m.group(2)]

def sigdigits(s):
    d = s.replace("-", "").replace(".", "").lstrip("0")
    return len(d.rstrip("0")) if set(d) <= {"0"} else len(d)

vals = [0.0]
